function Plain() { this.v = 1; }

function hydrate(v) {
  var r, k;
  if (typeof v === 'string') {
    if (v.indexOf('$fn:') === 0) { r = JSON.parse(v.slice(4)); return function () { return r; }; }
    if (v.indexOf('$date:') === 0) { return new Date(Date.UTC(Number(v.slice(6)), 0, 1)); }
    if (v === '$obj') { return new Plain(); }
    return v;
  }
  if (Array.isArray(v)) { return v.map(hydrate); }
  if (v && typeof v === 'object') { r = {}; for (k in v) { if (Object.prototype.hasOwnProperty.call(v, k)) { r[k] = hydrate(v[k]); } } return r; }
  return v;
}

/*!
 * The locals of a matrix pair: `left` takes value i, `right` value j (or a
 * list holding it, for `in`); "$missing" leaves the name unset.
 */
function pairLocals(i, j, inList) {
  var l = {};
  if (VALUES[i][1] !== '$missing') { l.a = hydrate(VALUES[i][1]); }
  if (inList) {
    l.c = VALUES[j][1] === '$missing' ? [] : [hydrate(VALUES[j][1])];
  } else if (VALUES[j][1] !== '$missing') {
    l.b = hydrate(VALUES[j][1]);
  }
  return l;
}

function asyncInstance(templates) {
  var loader = {
    async: true,
    resolve: function (to) { return to; },
    load: function (id, cb) {
      if (cb) { setImmediate(function () { cb(null, templates[id]); }); return undefined; }
      return templates[id];
    }
  };
  return new Engine({ autoescape: false, loader: loader });
}

/*!
 * Every job, rendered on the sync path: `diffs` names each output that
 * differs from the reference.
 */
function syncDiffs(jobs) {
  var inst = new Engine({ autoescape: false }), fns = {}, diffs = [];
  jobs.forEach(function (job) {
    var out;
    try {
      fns[job.tpl] = fns[job.tpl] || inst.compile(job.tpl);
      out = fns[job.tpl](job.locals());
    } catch (e) {
      out = 'THROW ' + e.message;
    }
    if (out !== job.want) { diffs.push(job.id + ': ' + out + ' (reference ' + job.want + ')'); }
  });
  return diffs;
}

/*!
 * Every job, rendered one after the other on the async render path.
 */
function asyncDiffs(jobs, done) {
  var templates = {}, names = {}, n = 0, diffs = [], inst, i = 0;
  jobs.forEach(function (job) {
    if (!names.hasOwnProperty(job.tpl)) { names[job.tpl] = '/t' + (n += 1); templates[names[job.tpl]] = job.tpl; }
  });
  inst = asyncInstance(templates);
  function next() {
    var job = jobs[i];
    if (!job) {
      try { expect(diffs).to.eql([]); } catch (e) { return done(e); }
      return done();
    }
    i += 1;
    inst.renderFile(names[job.tpl], job.locals(), function (err, out) {
      out = err ? 'THROW ' + err.message : out;
      if (out !== job.want) { diffs.push(job.id + ': ' + out + ' (reference ' + job.want + ')'); }
      next();
    });
  }
  next();
}

function matrixJobs(op, rows) {
  var jobs = [], tpl = op === 'in' ? '{% if a in c %}Y{% else %}N{% endif %}' : '{% if a ' + op + ' b %}Y{% else %}N{% endif %}';
  VALUES.forEach(function (a, i) {
    VALUES.forEach(function (b, j) {
      jobs.push({ id: op + ':' + a[0] + ':' + b[0], tpl: tpl, want: rows[i].charAt(j), locals: function () { return pairLocals(i, j, op === 'in'); } });
    });
  });
  return jobs;
}

function caseJobs(cases) {
  return cases.map(function (c) {
    return { id: c[0], tpl: c[1], want: c[3], locals: function () { return hydrate(c[2]); } };
  });
}

describe('@rhinostone/swig-jinja2 — `==` and `!=` under Python\'s equality, checked against Jinja2 3.1.6', function () {

  it('`==` over every pair of 31 values', function () {
    expect(syncDiffs(matrixJobs('==', EQ_ROWS))).to.eql([]);
  });

  it('`!=` over every pair of 31 values', function () {
    expect(syncDiffs(matrixJobs('!=', NE_ROWS))).to.eql([]);
  });

  it('operand shapes and scopes: literals, paths, subscripts, filters, logic, loops, macros, functions, dates', function () {
    expect(syncDiffs(caseJobs(CASES))).to.eql([]);
  });

  describe('on the async render path', function () {

    it('`==` over every pair of 31 values', function (done) {
      asyncDiffs(matrixJobs('==', EQ_ROWS), done);
    });

    it('`!=` over every pair of 31 values', function (done) {
      asyncDiffs(matrixJobs('!=', NE_ROWS), done);
    });

    it('operand shapes and scopes: literals, paths, subscripts, filters, logic, loops, macros, functions, dates', function (done) {
      asyncDiffs(caseJobs(CASES), done);
    });
  });
});
